registry = {}
def register(name, version, caps):
    registry[name] = {"version": version, "caps": set(caps)}
def find(cap):
    return [n for n, r in registry.items() if cap in r["caps"]]
register("indexer", "2.1", ["index", "search"]); register("parser", "1.0", ["parse"])
print("can index:", find("index"))
assert find("index") == ["indexer"]

ns = {}
def put(path, val):
    node = ns
    for part in path.split("."): node = node.setdefault(part, {})
    node["#"] = val
put("archive.index.v2", "indexer"); put("archive.parse.v1", "parser")
print("archive tools:", list(ns["archive"]))
assert set(ns["archive"]) == {"index", "parse"}

manifest = {"indexer": "==2.1", "python": ">=3.9"}
locked = {"indexer": "2.1.0", "python": "3.11.2"}
def satisfies(spec, ver): return True  # simplified check
print("locked:", locked)
assert all(satisfies(manifest[k], locked[k]) for k in manifest)

contract = {"/search": {"params": ["q"], "returns": "list"}}
def check(endpoint, params):
    need = contract[endpoint]["params"]
    return all(p in params for p in need)
print(check("/search", {"q": "mars"}), check("/search", {}))
assert check("/search", {"q": "x"}) and not check("/search", {})

announced = {}
def announce(name, caps): announced[name] = caps
def listen(): return dict(announced)
announce("indexer.local", ["index"]); announce("parser.local", ["parse"])
print("discovered:", listen())
assert set(listen()) == {"indexer.local", "parser.local"}

import time
now = time.monotonic()
entries = {"a": now + 30, "b": now - 5}
live = {k: v for k, v in entries.items() if v > now}
print("live entries:", list(live))
assert list(live) == ["a"]

policy = {"1.0": "retired", "2.0": "deprecated", "3.0": "active"}
def usable(v):
    return policy.get(v) in ("active", "deprecated")
print({v: usable(v) for v in policy})
assert not usable("1.0") and usable("2.0")

matrix = {("indexer-2", "parser-1"): True, ("indexer-2", "parser-2"): False}
def ok(a, b): return matrix.get((a, b), False)
print(ok("indexer-2", "parser-1"), ok("indexer-2", "parser-2"))
assert ok("indexer-2", "parser-1") and not ok("indexer-2", "parser-2")

entries = {"indexer": {"scopes": ["internal", "public"]}, "vault-tool": {"scopes": ["internal"]}}
def view(scopes):
    return [n for n, e in entries.items() if set(e["scopes"]) & set(scopes)]
print("public sees:", view(["public"]))
assert view(["public"]) == ["indexer"] and view(["internal"]) == ["indexer", "vault-tool"]

idx = {}
def add(name, text):
    for tok in text.lower().split(): idx.setdefault(tok, set()).add(name)
add("indexer", "fast full-text index search"); add("parser", "document parse tree")
print("search 'index':", idx.get("index"))
assert idx.get("index") == {"indexer"}
